components.css:
.ds-skip-link { position: absolute; top: 1rem; left: 1rem; padding: 0.75rem 1rem; background: var(--ink); color: var(--signal); z-index: 2; }
.ds-skip-link:not(:focus) { clip-path: inset(50%); width: 1px; height: 1px; overflow: hidden; }
.ds-skip-link:focus-visible { outline: 3px solid currentColor; outline-offset: 4px; }

.ds-main-nav ul { display: flex; flex-wrap: wrap; gap: 0.25rem 1.5rem; list-style: none; padding: 0; margin: 0; }
.ds-main-nav a { display: inline-flex; align-items: center; min-height: 2.75rem; color: var(--ink); text-decoration: underline; font: 700 0.875rem/1.6 var(--sans); text-transform: uppercase; }
.ds-main-nav a:hover, .ds-main-nav [aria-current="page"] { text-decoration-thickness: 4px; }
.ds-main-nav li:last-child a { padding-inline: 1rem; background: var(--ink); color: var(--signal); }
.ds-main-nav a:focus-visible { outline: 3px solid currentColor; outline-offset: 4px; }

.ds-project-context { background: var(--ink); color: var(--paper); }
.ds-project-title { margin: 1rem 0 0.75rem; font: 400 clamp(2rem, 4vw, 3.5rem)/1.08 var(--display); letter-spacing: -0.015em; text-transform: uppercase; }
.ds-project-link { color: var(--paper); text-decoration: underline; text-decoration-thickness: 2px; transition: background-color 0.18s cubic-bezier(.16, 1, .3, 1), color 0.18s cubic-bezier(.16, 1, .3, 1); }
.ds-project-link:hover, .ds-project-link:focus-visible { background: var(--signal); color: var(--ink); }
.ds-project-link:focus-visible { outline: 3px solid var(--signal); outline-offset: 4px; }
@media (prefers-reduced-motion: reduce) { .ds-project-link { transition: none; } }
@media (forced-colors: active) { .ds-project-link { text-decoration: underline; } }
